import heapq
import math


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _is_text(value):
    return isinstance(value, str) and value.strip() != ''


def _check_finite(obj):
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError('payload contains a non-finite number')
    elif isinstance(obj, dict):
        for v in obj.values():
            _check_finite(v)
    elif isinstance(obj, list):
        for v in obj:
            _check_finite(v)


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {'name', 'result'}:
        return payload['result']
    return payload


def _dijkstra(start, adj):
    dist = {start: 0}
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d != dist.get(u):
            continue
        for v, w in adj.get(u, ()):
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist


def _id_list(name, lst, node_set):
    if not isinstance(lst, list):
        raise ValueError(name + ' must be a list')
    result = []
    for item in lst:
        if not _is_text(item):
            raise ValueError(name + ' entries must be non-empty strings')
        if item not in node_set:
            raise ValueError(name + ' references unknown node: ' + item)
        result.append(item)
    return sorted(set(result))


def transform(payloads, contract):
    if len(payloads) != len(contract.get('inputs', [])):
        raise ValueError('payload count does not match contract inputs')
    for payload in payloads:
        _check_finite(payload)

    data = _unwrap(payloads[0])
    if not isinstance(data, dict):
        raise ValueError('route_graph input must be an object')

    for key in ('nodes', 'edges', 'sources', 'targets', 'failed_nodes', 'failed_edges'):
        if key not in data:
            raise ValueError('missing field: ' + key)

    nodes = data['nodes']
    edges = data['edges']
    sources = data['sources']
    targets = data['targets']
    failed_nodes = data['failed_nodes']
    failed_edges = data['failed_edges']

    if not isinstance(nodes, list):
        raise ValueError('nodes must be a list')
    for node in nodes:
        if not _is_text(node):
            raise ValueError('nodes entries must be non-empty strings')
    if len(set(nodes)) != len(nodes):
        raise ValueError('duplicate nodes')
    node_set = set(nodes)

    if not isinstance(edges, list):
        raise ValueError('edges must be a list')
    edge_set = set()
    edge_list = []
    for edge in edges:
        if not isinstance(edge, dict):
            raise ValueError('each edge must be an object')
        for key in ('from', 'to', 'weight'):
            if key not in edge:
                raise ValueError('edge is missing field: ' + key)
        frm = edge['from']
        to = edge['to']
        weight = edge['weight']
        if not _is_text(frm) or not _is_text(to):
            raise ValueError('edge endpoints must be non-empty strings')
        if not _is_int(weight) or weight < 1:
            raise ValueError('edge weight must be an int >= 1')
        if frm not in node_set or to not in node_set:
            raise ValueError('edge endpoint is not in nodes')
        key = (frm, to)
        if key in edge_set:
            raise ValueError('duplicate directed edge')
        edge_set.add(key)
        edge_list.append((frm, to, weight))

    sources = _id_list('sources', sources, node_set)
    targets = _id_list('targets', targets, node_set)
    failed_nodes = _id_list('failed_nodes', failed_nodes, node_set)

    if not isinstance(failed_edges, list):
        raise ValueError('failed_edges must be a list')
    failed_edge_set = set()
    for fe in failed_edges:
        if not isinstance(fe, list) or len(fe) != 2:
            raise ValueError('failed_edges entries must be [from, to]')
        frm, to = fe
        if not _is_text(frm) or not _is_text(to):
            raise ValueError('failed_edges endpoints must be non-empty strings')
        if (frm, to) not in edge_set:
            raise ValueError('failed_edge does not exist: ' + str((frm, to)))
        failed_edge_set.add((frm, to))

    failed_node_set = set(failed_nodes)
    fwd = {}
    rev = {}
    active_edges = []
    for frm, to, weight in edge_list:
        if frm in failed_node_set or to in failed_node_set:
            continue
        if (frm, to) in failed_edge_set:
            continue
        active_edges.append({'from': frm, 'to': to, 'weight': weight})
        fwd.setdefault(frm, []).append((to, weight))
        rev.setdefault(to, []).append((frm, weight))
    active_edges.sort(key=lambda e: (e['from'], e['to']))

    dist_from = {s: _dijkstra(s, fwd) for s in sources}
    dist_to = {t: _dijkstra(t, rev) for t in targets}

    routes = []
    inf = float('inf')
    for s in sources:
        for t in targets:
            if s in failed_node_set or t in failed_node_set:
                distance = None
                next_hops = []
            elif s == t:
                distance = 0
                next_hops = []
            else:
                df = dist_from[s]
                if t not in df:
                    distance = None
                    next_hops = []
                else:
                    d = df[t]
                    dt = dist_to[t]
                    hops = []
                    for v, w in fwd.get(s, ()):
                        if d == w + dt.get(v, inf):
                            hops.append(v)
                    hops.sort()
                    distance = d
                    next_hops = hops
            routes.append({
                'source': s,
                'target': t,
                'distance': distance,
                'next_hops': next_hops,
            })
    routes.sort(key=lambda r: (r['source'], r['target']))

    return {
        'name': contract['name'],
        'result': {
            'routes': routes,
            'active_edges': active_edges,
        },
    }

import fnmatch
import math


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _is_text(value):
    return isinstance(value, str) and value.strip() != ''


def _check_finite(obj):
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError('payload contains a non-finite number')
    elif isinstance(obj, dict):
        for v in obj.values():
            _check_finite(v)
    elif isinstance(obj, list):
        for v in obj:
            _check_finite(v)


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {'name', 'result'}:
        return payload['result']
    return payload


def _specificity(rule):
    text = rule['src'] + rule['dst'] + rule['protocol']
    return sum(1 for ch in text if ch not in '*?[]')


def _rule_sort_key(rule):
    deny_first = 0 if rule['effect'] == 'deny' else 1
    return (-rule['priority'], -_specificity(rule), deny_first, rule['id'])


def _rule_matches(rule, event):
    if not fnmatch.fnmatchcase(rule['src'], event['src']):
        return False
    if not fnmatch.fnmatchcase(rule['dst'], event['dst']):
        return False
    if rule['protocol'] != '*' and rule['protocol'] != event['protocol']:
        return False
    return True


def _session_key(event):
    endpoints = sorted([(event['src'], event['sport']), (event['dst'], event['dport'])])
    return (event['protocol'], endpoints[0], endpoints[1])


def transform(payloads, contract):
    if len(payloads) != len(contract.get('inputs', [])):
        raise ValueError('payload count does not match contract inputs')
    for payload in payloads:
        _check_finite(payload)

    data = _unwrap(payloads[0])
    if not isinstance(data, dict):
        raise ValueError('firewall_policy input must be an object')

    for key in ('timeout', 'rules', 'events'):
        if key not in data:
            raise ValueError('missing field: ' + key)

    timeout = data['timeout']
    if not _is_int(timeout) or timeout < 1:
        raise ValueError('timeout must be an int >= 1')

    rules = data['rules']
    events = data['events']
    if not isinstance(rules, list):
        raise ValueError('rules must be a list')
    if not isinstance(events, list):
        raise ValueError('events must be a list')

    rule_ids = set()
    parsed_rules = []
    for rule in rules:
        if not isinstance(rule, dict):
            raise ValueError('each rule must be an object')
        for key in ('id', 'src', 'dst', 'protocol', 'priority', 'effect'):
            if key not in rule:
                raise ValueError('rule is missing field: ' + key)
        rid = rule['id']
        if not _is_text(rid):
            raise ValueError('rule id must be non-empty text')
        if rid in rule_ids:
            raise ValueError('duplicate rule id')
        rule_ids.add(rid)
        if not _is_text(rule['src']) or not _is_text(rule['dst']):
            raise ValueError('rule src/dst must be non-empty text')
        if rule['protocol'] not in ('tcp', 'udp', '*'):
            raise ValueError('rule protocol must be tcp, udp or *')
        if not _is_int(rule['priority']):
            raise ValueError('rule priority must be an int')
        if rule['effect'] not in ('allow', 'deny'):
            raise ValueError('rule effect must be allow or deny')
        parsed_rules.append(rule)

    event_ids = set()
    parsed_events = []
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('each event must be an object')
        for key in ('id', 'ts', 'seq', 'src', 'dst', 'sport', 'dport', 'protocol', 'flag'):
            if key not in event:
                raise ValueError('event is missing field: ' + key)
        eid = event['id']
        if not _is_text(eid):
            raise ValueError('event id must be non-empty text')
        if eid in event_ids:
            raise ValueError('duplicate event id')
        event_ids.add(eid)
        if not _is_int(event['ts']) or event['ts'] < 0:
            raise ValueError('event ts must be an int >= 0')
        if not _is_int(event['seq']) or event['seq'] < 0:
            raise ValueError('event seq must be an int >= 0')
        if not _is_text(event['src']) or not _is_text(event['dst']):
            raise ValueError('event src/dst must be non-empty text')
        sport = event['sport']
        dport = event['dport']
        if not _is_int(sport) or not (1 <= sport <= 65535):
            raise ValueError('event sport must be an int in 1..65535')
        if not _is_int(dport) or not (1 <= dport <= 65535):
            raise ValueError('event dport must be an int in 1..65535')
        if event['protocol'] not in ('tcp', 'udp'):
            raise ValueError('event protocol must be tcp or udp')
        if event['flag'] not in ('syn', 'data', 'fin', 'rst'):
            raise ValueError('event flag must be syn/data/fin/rst')
        parsed_events.append(event)

    sorted_rules = sorted(parsed_rules, key=_rule_sort_key)
    sorted_events = sorted(parsed_events, key=lambda e: (e['ts'], e['seq'], e['id']))

    sessions = {}
    decisions = []
    for event in sorted_events:
        ts = event['ts']
        expired = [k for k, last in sessions.items() if ts >= last + timeout]
        for k in expired:
            del sessions[k]

        key = _session_key(event)
        if key in sessions:
            decisions.append({
                'id': event['id'],
                'allowed': True,
                'reason': 'state',
                'rule_id': None,
                'src': event['src'],
                'dst': event['dst'],
            })
            sessions[key] = ts
            if event['flag'] in ('fin', 'rst'):
                del sessions[key]
            continue

        if event['flag'] == 'syn':
            matched = next((r for r in sorted_rules if _rule_matches(r, event)), None)
            if matched is None:
                decisions.append({
                    'id': event['id'],
                    'allowed': False,
                    'reason': 'default',
                    'rule_id': None,
                    'src': event['src'],
                    'dst': event['dst'],
                })
            elif matched['effect'] == 'allow':
                decisions.append({
                    'id': event['id'],
                    'allowed': True,
                    'reason': 'rule',
                    'rule_id': matched['id'],
                    'src': event['src'],
                    'dst': event['dst'],
                })
                sessions[key] = ts
            else:
                decisions.append({
                    'id': event['id'],
                    'allowed': False,
                    'reason': 'rule',
                    'rule_id': matched['id'],
                    'src': event['src'],
                    'dst': event['dst'],
                })
        else:
            decisions.append({
                'id': event['id'],
                'allowed': False,
                'reason': 'no_session',
                'rule_id': None,
                'src': event['src'],
                'dst': event['dst'],
            })

    return {
        'name': contract['name'],
        'result': {
            'decisions': decisions,
            'active_sessions': len(sessions),
        },
    }

