def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _is_text(value):
    return isinstance(value, str) and value.strip() != ''


def _check_finite(obj):
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError('payload contains a non-finite number')
    elif isinstance(obj, dict):
        for v in obj.values():
            _check_finite(v)
    elif isinstance(obj, list):
        for v in obj:
            _check_finite(v)


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {'name', 'result'}:
        return payload['result']
    return payload


def transform(payloads, contract):
    inputs = contract.get('inputs', [])
    if len(payloads) != len(inputs):
        raise ValueError('payload count does not match contract inputs')
    for payload in payloads:
        _check_finite(payload)

    probes_data = _unwrap(payloads[0])
    ecmp = _unwrap(payloads[1])
    acl = _unwrap(payloads[2])

    if not isinstance(probes_data, dict) or 'probes' not in probes_data:
        raise ValueError('network_traces input must be an object with probes')
    probes = probes_data['probes']
    if not isinstance(probes, list):
        raise ValueError('probes must be a list')

    if not isinstance(ecmp, dict) or 'routes' not in ecmp or 'active_edges' not in ecmp:
        raise ValueError('ecmp result must contain routes and active_edges')
    if not isinstance(acl, dict) or 'decisions' not in acl:
        raise ValueError('acl result must contain decisions')

    routes = ecmp['routes']
    active_edges = ecmp['active_edges']
    decisions = acl['decisions']
    if not isinstance(routes, list) or not isinstance(active_edges, list) or not isinstance(decisions, list):
        raise ValueError('upstream result fields must be lists')

    probe_ids = set()
    for probe in probes:
        if not isinstance(probe, dict):
            raise ValueError('each probe must be an object')
        for key in ('id', 'event', 'source', 'target', 'hops'):
            if key not in probe:
                raise ValueError('probe is missing field: ' + key)
        pid = probe['id']
        if not _is_text(pid):
            raise ValueError('probe id must be non-empty text')
        if pid in probe_ids:
            raise ValueError('duplicate probe id')
        probe_ids.add(pid)
        if not _is_text(probe['event']):
            raise ValueError('probe event must be non-empty text')
        if not _is_text(probe['source']) or not _is_text(probe['target']):
            raise ValueError('probe source/target must be non-empty text')
        hops = probe['hops']
        if not isinstance(hops, list):
            raise ValueError('probe hops must be a list')
        for hop in hops:
            if not _is_text(hop):
                raise ValueError('probe hops entries must be non-empty text')

    route_by_pair = {}
    for route in routes:
        if not isinstance(route, dict):
            raise ValueError('each route must be an object')
        for key in ('source', 'target', 'distance', 'next_hops'):
            if key not in route:
                raise ValueError('route is missing field: ' + key)
        if not _is_text(route['source']) or not _is_text(route['target']):
            raise ValueError('route source/target must be non-empty text')
        distance = route['distance']
        if distance is not None and not _is_int(distance):
            raise ValueError('route distance must be an int or null')
        if not isinstance(route['next_hops'], list):
            raise ValueError('route next_hops must be a list')
        key = (route['source'], route['target'])
        if key in route_by_pair:
            raise ValueError('duplicate route pair')
        route_by_pair[key] = route

    edge_weight = {}
    for edge in active_edges:
        if not isinstance(edge, dict):
            raise ValueError('each active edge must be an object')
        for key in ('from', 'to', 'weight'):
            if key not in edge:
                raise ValueError('active edge is missing field: ' + key)
        if not _is_text(edge['from']) or not _is_text(edge['to']):
            raise ValueError('active edge endpoints must be non-empty text')
        if not _is_int(edge['weight']) or edge['weight'] < 1:
            raise ValueError('active edge weight must be an int >= 1')
        key = (edge['from'], edge['to'])
        if key in edge_weight:
            raise ValueError('duplicate active edge')
        edge_weight[key] = edge['weight']

    acl_by_id = {}
    for decision in decisions:
        if not isinstance(decision, dict):
            raise ValueError('each decision must be an object')
        for key in ('id', 'allowed', 'src', 'dst'):
            if key not in decision:
                raise ValueError('decision is missing field: ' + key)
        if not _is_text(decision['id']):
            raise ValueError('decision id must be non-empty text')
        if decision['id'] in acl_by_id:
            raise ValueError('duplicate decision id')
        if not isinstance(decision['allowed'], bool):
            raise ValueError('decision allowed must be a bool')
        if not _is_text(decision['src']) or not _is_text(decision['dst']):
            raise ValueError('decision src/dst must be non-empty text')
        acl_by_id[decision['id']] = decision

    results = []
    for probe in probes:
        event_id = probe['event']
        decision = acl_by_id.get(event_id)
        if decision is None:
            raise ValueError('unknown event: ' + event_id)

        if decision['allowed'] is not True or decision['src'] != probe['source'] or decision['dst'] != probe['target']:
            results.append({'id': probe['id'], 'reachable': False, 'reason': 'acl'})
            continue

        route = route_by_pair.get((probe['source'], probe['target']))
        if route is None or route['distance'] is None:
            results.append({'id': probe['id'], 'reachable': False, 'reason': 'route'})
            continue

        distance = route['distance']
        hops = probe['hops']

        if len(hops) < 1 or hops[0] != probe['source'] or hops[-1] != probe['target']:
            results.append({'id': probe['id'], 'reachable': False, 'reason': 'path'})
            continue

        total = 0
        path_ok = True
        for i in range(len(hops) - 1):
            key = (hops[i], hops[i + 1])
            if key not in edge_weight:
                path_ok = False
                break
            total += edge_weight[key]
        if not path_ok:
            results.append({'id': probe['id'], 'reachable': False, 'reason': 'path'})
            continue

        first_hop_ok = True
        if distance > 0:
            if len(hops) < 2 or hops[1] not in route['next_hops']:
                first_hop_ok = False

        if total != distance or not first_hop_ok:
            results.append({'id': probe['id'], 'reachable': False, 'reason': 'non_shortest'})
            continue

        results.append({'id': probe['id'], 'reachable': True, 'reason': 'ok'})

    reachable_count = sum(1 for r in results if r['reachable'])

    return {
        'name': contract['name'],
        'result': {
            'results': results,
            'reachable_count': reachable_count,
        },
    }

import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _contracts():
    result = []
    for p in sorted(ROOT.rglob('contract.json')):
        if 'outputs' in p.relative_to(ROOT).parts:
            continue
        result.append(p)
    return result


def _load(path):
    return json.loads(path.read_text(encoding='utf-8'))


def main():
    contracts = _contracts()
    if not contracts:
        raise ValueError('no component contracts found')

    output_to_contract = {}
    for path in contracts:
        contract = _load(path)
        output_to_contract[contract['output']] = path

    dependencies = {}
    for path in contracts:
        contract = _load(path)
        deps = []
        for inp in contract['inputs']:
            dep = output_to_contract.get(inp)
            if dep is not None and dep != path:
                deps.append(dep)
        dependencies[path] = sorted(set(deps))

    order = []
    state = {}

    def visit(path):
        status = state.get(path, 0)
        if status == 2:
            return
        if status == 1:
            raise ValueError('dependency cycle among component contracts')
        state[path] = 1
        for dep in dependencies[path]:
            visit(dep)
        state[path] = 2
        order.append(path)

    for path in contracts:
        visit(path)

    for path in order:
        script = path.with_name('render.py')
        subprocess.run([sys.executable, str(script)], cwd=ROOT, check=True)

    subprocess.run([sys.executable, str(ROOT / 'integrate.py')], cwd=ROOT, check=True)
    subprocess.run([sys.executable, str(ROOT / 'final_report.py')], cwd=ROOT, check=True)


if __name__ == '__main__':
    main()

